class Solution:
    def minPrimes(self, n: int, m: int) -> int:
        sieve = [True] * (n + 1)
        if n >= 0: sieve[0:min(2, n + 1)] = [False] * min(2, n + 1)
        for i in range(2, int(n ** .5) + 1):
            if sieve[i]:
                for j in range(i * i, n + 1, i): sieve[j] = False
        primes = [i for i in range(2, n + 1) if sieve[i]][:m]
        INF = float('inf')
        dp = [0] + [INF] * n
        for s in range(1, n + 1):
            for p in primes:
                if p > s: break
                if dp[s - p] + 1 < dp[s]: dp[s] = dp[s - p] + 1
        return dp[n] if dp[n] < INF else -1

