class Solution {
public:
    int minPrimes(int n, int m) {
        vector<bool> sieve(n + 1, true);
        if (n >= 0) { if (n >= 0) sieve[0] = false; if (n >= 1) sieve[1] = false; }
        for (int i = 2; i * i <= n; i++)
            if (sieve[i]) for (int j = i * i; j <= n; j += i) sieve[j] = false;
        vector<int> primes;
        for (int i = 2; i <= n && (int)primes.size() < m; i++) if (sieve[i]) primes.push_back(i);
        const int INF = 1e9;
        vector<int> dp(n + 1, INF); dp[0] = 0;
        for (int s = 1; s <= n; s++)
            for (int p : primes) { if (p > s) break; dp[s] = min(dp[s], dp[s - p] + 1); }
        return dp[n] >= INF ? -1 : dp[n];
    }
};

