from collections import deque
class Solution:
    def minPrimes(self, n: int, m: int) -> int:
        sieve = [True] * (n + 1)
        for i in range(2, int(n ** .5) + 1):
            if sieve[i]:
                for j in range(i*i, n + 1, i): sieve[j] = False
        primes = [i for i in range(2, n + 1) if sieve[i]][:m]
        dist = [-1] * (n + 1); dist[0] = 0
        q = deque([0])
        while q:
            s = q.popleft()
            for p in primes:
                if s + p > n: break
                if dist[s + p] == -1:
                    dist[s + p] = dist[s] + 1
                    q.append(s + p)
        return dist[n]

